#!/bin/bash

# Copyright (c) 2026 Battelle Energy Alliance, LLC.  All rights reserved.

# Runs Arkime Parliament or Cont3xt (selected by the first argument) in the foreground.
#   This is started by supervisord when the container's run mode (ARKIME_RUN_MODE, or the
#   first argument passed to the container; see docker_entrypoint.sh) is "parliament" or
#   "cont3xt". The config file it uses ($ARKIME_DIR/etc/<component>.ini) is generated by
#   docker_entrypoint.sh unless one was provided.

COMPONENT="${1:-}"
ARKIME_DIR=${ARKIME_DIR:-"/opt/arkime"}
OPENSEARCH_PRIMARY=${OPENSEARCH_PRIMARY:-"opensearch-local"}
OPENSEARCH_SSL_CERTIFICATE_VERIFICATION=${OPENSEARCH_SSL_CERTIFICATE_VERIFICATION:-"false"}

case "${COMPONENT}" in
  parliament|cont3xt)
    ;;
  *)
    echo "Usage: $(basename "$0") <parliament|cont3xt>" >&2
    exit 1
    ;;
esac

COMPONENT_DIR="${ARKIME_DIR}/${COMPONENT}"
COMPONENT_SCRIPT="${COMPONENT_DIR}/${COMPONENT}.js"
CONFIG_FILE="${ARKIME_DIR}/etc/${COMPONENT}.ini"

if [[ ! -f "${COMPONENT_SCRIPT}" ]]; then
  echo "ERROR: ${COMPONENT_SCRIPT} does not exist in this image" >&2
  exit 1
fi
if [[ ! -r "${CONFIG_FILE}" ]]; then
  echo "ERROR: ${CONFIG_FILE} does not exist or is not readable" >&2
  exit 1
fi

# make sure TLS certificates exist prior to starting up, if the config file references them
if [[ "${ARKIME_SSL:-true}" != "false" ]] && [[ -x /usr/local/bin/self_signed_key_gen.sh ]]; then
  CERT_FILE="$(grep -Pi '^\s*certFile\s*=' "${CONFIG_FILE}" | head -n 1 | cut -d'=' -f2- | xargs)"
  KEY_FILE="$(grep -Pi '^\s*keyFile\s*=' "${CONFIG_FILE}" | head -n 1 | cut -d'=' -f2- | xargs)"
  if [[ -n "${CERT_FILE}" ]] && [[ -n "${KEY_FILE}" ]] && ( [[ ! -f "${CERT_FILE}" ]] || [[ ! -f "${KEY_FILE}" ]] ); then
    CERT_TMP_DIR="$(mktemp -d)"
    if /usr/local/bin/self_signed_key_gen.sh -n -o "${CERT_TMP_DIR}" >/dev/null 2>&1 && \
       mv "${CERT_TMP_DIR}"/server.crt "${CERT_FILE}" && \
       mv "${CERT_TMP_DIR}"/server.key "${KEY_FILE}"; then
      echo "Generated self-signed TLS certificate for ${COMPONENT}"
    else
      echo "WARNING: unable to generate TLS certificate (${CERT_FILE}, ${KEY_FILE}) for ${COMPONENT}" >&2
    fi
    rm -rf "${CERT_TMP_DIR}"
  fi
fi

# both Parliament (for users) and Cont3xt (for users and its own data) use OpenSearch/Elasticsearch
echo "Giving ${OPENSEARCH_PRIMARY} time to start..."
/usr/local/bin/opensearch_status.sh 2>&1 && echo "${OPENSEARCH_PRIMARY} is running!"

# Both exit immediately if the Arkime users index doesn't exist yet, so (like arkime-live) wait
#   for the arkime container (or db.pl init, if run standalone) to initialize the database
#   rather than crash-looping
OPENSEARCH_URL=${OPENSEARCH_URL:-"https://opensearch:9200"}
OPENSEARCH_CREDS_CONFIG_FILE=${OPENSEARCH_CREDS_CONFIG_FILE:-"/var/local/curlrc/.opensearch.primary.curlrc"}
CURL_CONFIG_PARAMS=()
[[ -r "${OPENSEARCH_CREDS_CONFIG_FILE}" ]] && CURL_CONFIG_PARAMS=( --config "${OPENSEARCH_CREDS_CONFIG_FILE}" )
echo "Waiting for the Arkime database to be initialized..."
WAIT_COUNT=0
until (( $(curl "${CURL_CONFIG_PARAMS[@]}" -fs -XGET -H'Content-Type: application/json' "${OPENSEARCH_URL}/_cat/indices/arkime_users_v*" 2>/dev/null | wc -l) >= 1 )); do
  (( ++WAIT_COUNT % 60 == 0 )) && echo "Still waiting for the Arkime database (arkime_users) to be initialized..."
  sleep 5
done
echo "Arkime database is initialized!"

NODE_ARGS=( -c "${CONFIG_FILE}" )
[[ "${OPENSEARCH_SSL_CERTIFICATE_VERIFICATION}" != "true" ]] && NODE_ARGS+=( --insecure )

echo "Launch ${COMPONENT}..."
cd "${COMPONENT_DIR}" || exit 1
exec "${ARKIME_DIR}"/bin/node "${COMPONENT}.js" "${NODE_ARGS[@]}"
